    elif k=='array': yield [z for c in f.children for z in ev(c,inp,env)]
    elif k=='object':
        out={}
        for key,c in f.value:
            keys = list(ev(key, inp, env))
            vals = list(ev(c, inp, env))
            for actual_key in keys:
                out[str(actual_key)] = vals[-1] if vals else None
        yield out
