        try: yield from ev(f.children[0], inp, env)
        except RuntimeJqError: return
    elif k == 'try':
        try:
            yield from ev(f.children[0], inp, env)
        except RuntimeJqError as error:
            if f.children[1].kind != 'empty':
                yield from ev(f.children[1], str(error), env)
    elif k == 'label':
        try:
            yield from ev(f.children[0], inp, env)
        except BreakSignal:
            return
    elif k == 'break':
        raise BreakSignal()
