        ka, kb = rank.get(type(a), 6), rank.get(type(b), 6)
        if ka != kb: comparison = ka - kb
        elif isinstance(a, dict): comparison = (list(sorted(a)) > list(sorted(b))) - (list(sorted(a)) < list(sorted(b)))
        else: comparison = (a > b) - (a < b)
        return {'<': comparison < 0, '>': comparison > 0,
                '<=': comparison <= 0, '>=': comparison >= 0}[op]
